```rust
wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

struct Node;

impl Guest for Node {
    fn run(reply: AgentResponse) -> DeliveryConfirmation {
        let confirmation = crate::aap::caps::response_channel::send(&reply.text);

        // The ensures clause must hold of every output. The host supplies the
        // session identity and the delivery flag, so the guest cannot repair
        // them. If either fails, trap rather than return a confirmation that
        // violates the contract.
        if !confirmation.delivered {
            panic!("SendReply: response channel did not deliver the reply");
        }
        if confirmation.session.is_empty() {
            panic!("SendReply: delivery confirmation carried no session id");
        }

        confirmation
    }
}

export!(Node);
